import duckdb,boto3,json
cr=boto3.Session(profile_name='scrapivo').get_credentials().get_frozen_credentials(); c=duckdb.connect(); c.execute('LOAD httpfs'); c.execute("SET s3_region='us-east-2'"); c.execute("SET s3_access_key_id=?",[cr.access_key]); c.execute("SET s3_secret_access_key=?",[cr.secret_key]);
if cr.token:c.execute("SET s3_session_token=?",[cr.token])
c.execute("create view d as select * from read_parquet('s3://scrapivo-raw-data-2026-523220341033-us-east-2-an/processed/investors/investor.parquet')")
q="""select count(*) total,count(distinct location_country) countries,count(distinct location_city) cities,count(distinct kind) kinds,sum((website is not null and trim(website)<>'')::int) website,sum((email is not null and trim(email)<>'')::int) email,sum((linkedin is not null and trim(linkedin)<>'')::int) linkedin,sum((bio is not null and trim(bio)<>'')::int) bio,sum((sectors is not null and len(sectors)>0)::int) sectors,sum((stages is not null and len(stages)>0)::int) stages,sum((check_min_usd is not null or check_max_usd is not null)::int) check_size,count(*)-count(distinct id) duplicate_ids from d"""
r=c.execute(q); out=dict(zip([x[0] for x in r.description],r.fetchone())); out['top_countries']=c.execute("select location_country,count(*) n from d group by location_country order by n desc limit 20").fetchall(); out['top_kinds']=c.execute("select kind,count(*) n from d group by kind order by n desc limit 20").fetchall(); out['top_sectors']=c.execute("select sector,count(*) n from d, unnest(sectors) as t(sector) group by sector order by n desc limit 25").fetchall();
open('reports/gate2/_investor-profile.json','w').write(json.dumps(out,indent=2,default=str)); print(json.dumps(out,default=str))